def telepathy():
    result=[]
    def add(prompt,topic,difficulty='easy'):
        result.append({'prompt':prompt,'topic':topic,'difficulty':difficulty})
    for world in WORLDS.split('|'):
        for template in CHARACTER_DECISIONS: add(template.format(world=world),'personajes de ficción','medium')
    for domain in BRANDS.split('|'):
        for template in BRAND_DECISIONS: add(template.format(domain=domain),'marcas','medium' if domain in ('pianos','guitarras','joyas','colchones','herramientas') else 'easy')
    for food in FOODS.split('|'):
        for template in FOOD_DECISIONS: add(template.format(food=food),'gastronomía')
    for person in REAL_PEOPLE.split('|'):
        for template in PERSON_DECISIONS: add(template.format(person=person),'personajes reales','hard' if any(term in person for term in ('científica','inventora','exploradora','escultora','poeta','clásica','bailarina','astronauta')) else 'medium')
    for prompt in DIRECT.split('|'): add(prompt,'temas clásicos')
    return result
